import subprocess
import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("Interval and duration must be greater than zero")
    system = platform.system()
    if system == "Windows":
        command = ['wmic', 'cpu', 'get', 'loadpercentage']
    else:
        command = ['top', '-bn1']
    records = []
    end_time = time.time() + duration
    while time.time() < end_time:
        output = subprocess.check_output(command).decode('utf-8')
        if system == "Windows":
            lines = output.strip().split('\n')
            if len(lines) > 1:
                cpu_usage = lines[1].strip()
            else:
                cpu_usage = "0"
        else:
            lines = output.split('\n')
            for line in lines:
                if '%Cpu(s)' in line:
                    parts = line.split(',')
                    idle = parts[3].strip().split(' ')[0]
                    cpu_usage = str(100.0 - float(idle))
                    break
            else:
                cpu_usage = "0"
        records.append({'timestamp': time.time(), 'cpu_usage': cpu_usage})
        time.sleep(interval)
    try:
        with open(LOGFILE_PATH, 'w') as f:
            json.dump(records, f)
    except IOError:
        return None
    return LOGFILE_PATH

